//! Precomputed fixed-base table for P-256 `[k]G`.
//!
//! With `B = 2^COMB_W` ([`super::p256::COMB_W`]),
//! `P256_GEN_TABLE[i][j]` is the affine point `[(2j + 1)·B^i]G` for
//! `i in 0..COMB_WINDOWS`, `j in 0..COMB_ENTRIES` (`COMB_ENTRIES =
//! 2^(COMB_W − 1)`) — the odd multiples the signed-digit comb needs (a
//! negative digit negates `y`), half the entries of a full `1..B` window —
//! and `P256_GEN_TOP` is `[B^COMB_WINDOWS]G`, the comb's starting point. The
//! first window doubles as the width-`COMB_W + 1` wNAF table of `G` for
//! verification. Entries are stored as
//! `[x_0, x_1, x_2, x_3, y_0, y_1, y_2, y_3]` — little-endian 64-bit limbs of
//! the x then y coordinates, in **Montgomery form** (`a·R mod p`, the native
//! field representation of [`super::p256_field`]), ready for
//! [`super::p256::P256::mul_generator`] to use without any conversion. No
//! entry is the identity (`(2j + 1)·B^i` and `B^COMB_WINDOWS` are never
//! multiples of the prime group order `n`), so a plain `Z = 1` lift is
//! always valid.
//!
//! Generated by the `#[ignore]`d test `ec::p256::tests::gen_p256_gen_table`
//! (`cargo test --release --no-default-features --features ec,std,hash,rng
//! --lib gen_p256_gen_table -- --ignored --nocapture`, which runs without
//! this file); the always-run test `ec::p256::tests::gen_table_matches_computed`
//! re-derives every entry from the group law on each test run, so these
//! constants are verified, not trusted.

